zarm() {   # Z = ALL: ar_xpush 1 (XPON), gg_gemv_m16 1 (A4ON), ds41_bi 6, gg_pf 2 (A11ON), place_swap_lent 1 + heat_min_gain_x100 SWLG (SWLON);
           # SA14_SW=0 (the mock): {} (ref14: Z = O, the int14 pin)
  [ $SW = 1 ] || { echo '{}'; return 0; }
  python3 -c 'import json,sys
xp, a4, a11, swl, g = (int(x) for x in sys.argv[1:6])
d = {"ds41_bi": 6, "ar_xpush": 1 if xp else 0, "gg_gemv_m16": 1 if a4 else 0, "gg_pf": 2 if a11 else 1}
d.update({"place_swap_lent": 1, "heat_min_gain_x100": g} if swl else {"place_swap_lent": 0, "heat_min_gain_x100": 150})
print(json.dumps(d))' $XPON $A4ON $A11ON $SWLON $SWLG
}
swlwant() { case $1 in O|W|B|S1|S2) echo "1 $SWLG" ;; Z) [ $SWLON = 1 ] && echo "1 $SWLG" || echo "0 150" ;; *) echo "0 150" ;; esac; }   # ARM -> place_swap_lent heat_min_gain_x100 (yswl's blockx checks the ranks)
armj() {   # armj ARM: the arm's own switch (JSON) on top of the base; under SA14_SW=0 only the int8 switches (F4, C1T)
  case $1 in
    O) echo '{}' ;;
    M0) [ $SW = 1 ] && echo '{"ds41_mix_wv": 0}' || echo '{}' ;;
    MX) [ $SW = 1 ] && echo "{\"ds41_mix_wv\": $MXV}" || echo '{}' ;;
    MX12) [ $SW = 1 ] && echo '{"ds41_mix_wv": 12}' || echo '{}' ;;
    GQ) [ $SW = 1 ] && echo '{"ds41_gq": 3}' || echo '{}' ;;
    E2) [ $SW = 1 ] && echo '{"ds41_e2": 1}' || echo '{}' ;;
    F4) echo '{"ds41_shexp_lane": 1}' ;;
    B) echo '{}' ;;   # zsa14: B = THE int14 PIN with lever SA off (the base pin's stage_short 0, stage_pick 0) = ref14's O
    S1) echo "{\"stage_short\": $SSN, \"stage_pick\": $PK1}" ;;   # lever SA: the prefill stager armed for steps of >= SSN tokens at the span's shared level, pick K1
    S2) echo "{\"stage_short\": $SSN, \"stage_pick\": $PK2}" ;;   # lever SA, pick K2 (pre-move: the fastest pick of the usahb screen)
    A) [ $SW = 1 ] && echo '{"ds41_bi": 6}' || echo '{}' ;;   # lever A9: one MoE all-reduce a segmented step (6 = 4 + the one all-reduce)
    G) [ $SW = 1 ] && echo '{"gg_pf": 2}' || echo '{}' ;;   # lever A11: the P0 table's ranged entries
    C) [ $SW = 1 ] && echo '{"gg_gemv_m16": 1}' || echo '{}' ;;   # lever A4: the A4 table's forms (/stats/m16-forms.txt)
    X) [ $SW = 1 ] && echo '{"ar_xpush": 1}' || echo '{}' ;;   # XPUSH (no read of its own here: its screen ran; in Z)
    W) [ $SW = 1 ] && echo "{\"place_swap_lent\": 1, \"heat_min_gain_x100\": $SWLG}" || echo '{}' ;;   # SWL's winner (yswl's L1G075)
    Z) zarm ;;   # ALL: every lever whose P0 passed
    Q) [ $SW = 1 ] && echo '{"ds41_bi": 4, "gg_pf": 1}' || echo '{}' ;;   # (kept from ync: ds41_bi 4, the cheap issue without the one all-reduce)
    C*) echo "{\"dspark_conf\": ${1#C}}" ;;
    H*) [ $SW = 1 ] && echo "{\"sched_cb_hold_ms\": ${1#H}, \"sched_cb_hold_k\": $CBHK}" || echo '{}' ;;
    NH) python3 -c 'import json,sys
sw, mxv, mx, gq, e2 = sys.argv[1] == "1", int(sys.argv[2]), sys.argv[3] == "1", sys.argv[4] == "1", sys.argv[5] == "1"
d = {"ds41_shexp_lane": 1 if sys.argv[6] == "1" else 0}
if sw:
    if mx: d["ds41_mix_wv"] = mxv
    if gq: d["ds41_gq"] = 3
    if e2: d["ds41_e2"] = 1
    if sys.argv[7] == "NH": d.update(sched_cb_hold_ms=500, sched_cb_hold_k=int(sys.argv[8]))
print(json.dumps(d))' $SW $MXV $MXOK $GQOK $E2OK $F4OK $1 $CBHK ;;
  esac
}
