rankrb() {   # rankrb TAG: THE int14 PIN READ BACK right after swnote posted it -- GET /admin/fn4: every switch of the pin (pinj O) applied, nothing
             # pending, the int14 values named; GET /stats experts.ranks: FOUR ranks, each place_swl 1, heat_min_gain_x100 SWLG, heat_hyst_x100
             # 125, place_lf 0 (SWL lives in each rank's mover) -> 0; else VIRHE -> 1 (not read) (SA14_SW=0: INFO, 0)
  [ "$DRY" = 1 ] && { echo "+ RESULT xsa14 $1: THE int14 PIN read back -- GET /admin/fn4 ds41_bi 6, gg_pf 2, ar_xpush 1, gg_gemv_m16 1, place_swap_lent 1, heat_min_gain_x100 $SWLG, heat_hyst_x100 125 (+ every other switch of the pin), nothing pending; GET /stats on each of the 4 ranks place_swl 1, heat_min_gain_x100 $SWLG, heat_hyst_x100 125, place_lf 0 (else VIRHE: not read)"; return 0; }
  local r
